  async function beforeProvider(uid,orderId){await store.transaction(async tx=>{const p=`billingOrders/${orderId}`,order=await tx.get(p);if(!order?.snapshot?.referral)return;const b=await tx.get(`referralBindings/${uid}`);if(b?.discountOrderId!==orderId)fail(409,'ORDER_CONFLICT','Invitationens betaling er ændret. Prøv igen.');tx.set(p,{...order,providerAttemptStartedAt:order.providerAttemptStartedAt||iso(now())});});}
