  async function cronAuth(header){const expected=env.CRON_SECRET;if(!expected||expected.length<24)fail(503,'CRON_DISABLED','Belønningskørslen er ikke aktiveret.');const actual=typeof header==='string'?header:'';const wanted=`Bearer ${expected}`;if(Buffer.byteLength(actual)!==Buffer.byteLength(wanted)||!timingSafeEqual(Buffer.from(actual),Buffer.from(wanted)))fail(401,'CRON_AUTH_INVALID','Ugyldig adgang.');}
