  async function process(){config();if(!stripe||!/^(sk|rk)_test_/.test(env.STRIPE_SECRET_KEY||'')||!store.list)fail(503,'REFERRAL_PROCESS_DISABLED','Belønningskørslen er ikke aktiveret.');const jobs=await store.list('referralPaymentJobs',{status:['held','refund_pending'],eligibleBefore:iso(now()),limit:100});const results=[];for(const job of jobs){try{results.push({id:job.id,...await processJob(job)});}catch{results.push({id:job.id,status:'review_required'});}}return {processed:results.length,results};}
